import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;

@WebServlet("/greet")
public class GreetServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        // 無いときは null が来る。空文字も一緒に弾いておく
        String name = req.getParameter("name");
        if (name == null || name.isEmpty()) {
            name = "ゲスト";
        }

        // 数値の変換は必ず失敗しうる
        int age = -1;
        String rawAge = req.getParameter("age");
        if (rawAge != null) {
            try {
                age = Integer.parseInt(rawAge);
            } catch (NumberFormatException e) {
                age = -1;
            }
        }

        res.getWriter().println("name=" + name + " age=" + age);

        // 同じ名前が複数あるとき
        String[] colors = req.getParameterValues("color");
        res.getWriter().println("color(1つ) =" + req.getParameter("color"));
        res.getWriter().println("color(全部)=" + (colors == null ? "なし" : String.join(",", colors)));
    }

    public static void main(String[] args) {
        MiniWeb.app().register(GreetServlet.class).echoRequests().serve();
    }
}

