import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;
import java.io.*;
import java.util.*;

@WebServlet("/items")
public class ItemServlet extends HttpServlet {
    private final Set<Integer> ids = new HashSet<>(Set.of(1, 2));

    private Integer id(HttpServletRequest req, HttpServletResponse res) throws IOException {
        try {
            return Integer.parseInt(req.getParameter("id"));
        } catch (RuntimeException e) {
            res.sendError(400, "idは整数です");
            return null;
        }
    }

    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        Integer id = id(req, res);
        if (id == null) return;
        if (!ids.contains(id)) {
            res.sendError(404, "itemが見つかりません");
            return;
        }
        res.getWriter().println("item-" + id);
    }

    protected void doDelete(HttpServletRequest req, HttpServletResponse res) throws IOException {
        Integer id = id(req, res);
        if (id == null) return;
        if (!ids.remove(id)) {
            res.sendError(404, "itemが見つかりません");
            return;
        }
        res.setStatus(204);
    }

    public static void main(String[] a) {
        MiniWeb.app().register(ItemServlet.class).serve();
    }
}

