import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;
import java.io.*;

@WebServlet("/search")
public class SearchServlet extends HttpServlet {
    static String escapeHtml(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;");
    }

    protected void doGet(HttpServletRequest q, HttpServletResponse s) throws IOException {
        s.setContentType("text/html; charset=UTF-8");
        s.getWriter().println("検索: " + escapeHtml(q.getParameter("q")));
    }

    public static void main(String[] a) {
        MiniWeb.app().register(SearchServlet.class).showHeaders().serve();
    }
}

